-- Synthetic transaction only: runner inserts the exact migration at the marker.
RESET ROLE; SET session_replication_role=replica;
INSERT INTO public.dms_upload_sessions(id,session_code,original_filename,mime_type,file_size_bytes,sha256_hash,temp_storage_path,uploaded_by,expires_at,owning_company_id,owning_branch_id,intake_status) OVERRIDING SYSTEM VALUE VALUES(1101,'SYN-VERIFY-1101','SYNTHETIC.pdf','application/pdf',10,repeat('d',64),'synthetic/verify.pdf',1001,now()+interval '1 hour',1001,1001,'review_pending');
INSERT INTO storage.buckets(id,name) VALUES('dms-temp','dms-temp') ON CONFLICT DO NOTHING;
INSERT INTO storage.objects(id,bucket_id,name,version,metadata) VALUES('00000000-0000-4000-8000-000000003001','dms-temp','synthetic/verify.pdf','synthetic-v1','{"size":10,"mimetype":"application/pdf"}');
INSERT INTO public.dms_ai_extraction_jobs(id,upload_session_id,job_type,status,input_text_hash,created_by) OVERRIDING SYSTEM VALUE VALUES(1101,1101,'classify_extract','complete',repeat('d',64),1001);
