UPDATE public.dms_upload_sessions SET ai_result_id=1101 WHERE id=1101;
SELECT setval(pg_get_serial_sequence('public.dms_ai_extraction_results','id'),1101);
SELECT setval(pg_get_serial_sequence('public.dms_ai_extraction_jobs','id'),1101);
SET session_replication_role=origin;
SELECT set_config('test.source',(SELECT erp_private.f07_intake_source_row(s)::text FROM public.dms_upload_sessions s WHERE id=1101),false);
SELECT set_config('test.updated',(SELECT date_trunc('milliseconds',updated_at)::text FROM storage.objects WHERE name='synthetic/verify.pdf'),false);
SELECT set_config('test.root',(SELECT to_jsonb(a)::text FROM public.dms_ai_extraction_results a WHERE id=1101),false);
SELECT set_config('request.jwt.claims','{"role":"service_role"}',false); SET ROLE service_role;
SELECT public.f07_attest_intake_source(1101,1001,'00000000-0000-4000-8000-000000002001',current_setting('test.source')::jsonb,'00000000-0000-4000-8000-000000003001','synthetic-v1',current_setting('test.updated')::timestamptz,repeat('d',64));
SELECT public.f07_attest_intake_analysis(1101,1001,'00000000-0000-4000-8000-000000002001',1101,current_setting('test.root')::jsonb);
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001001","role":"authenticated","session_id":"00000000-0000-4000-8000-000000002001"}',false); SET ROLE authenticated;
SELECT pg_temp.ok(NOT (public.f07_prepare_intake_review(1101,1001,NULL)->>'requiresOverride')::boolean,'verified root is accepted for ordinary human review');
SELECT set_config('test.request','{"uploadSessionId":1101,"documentTypeId":1001,"mergeMode":"replace_ai_values"}',false);
SELECT set_config('test.stage',public.ai_mod04_intake_stage('begin',current_setting('test.request')::jsonb)::text,false);
SELECT pg_temp.ok(current_setting('test.stage')::jsonb->>'state'='started','baseline type extraction admitted');
RESET ROLE; SELECT set_config('request.jwt.claims','{"role":"service_role"}',false); SET ROLE service_role;
SELECT set_config('test.publish',jsonb_build_object('token',current_setting('test.stage')::jsonb->>'token','fields','{"number":"NEW"}'::jsonb,'confidence','{"number":{"score":0.9,"label":"high","source_snippet":"NEW number"}}'::jsonb,'preparation',jsonb_build_object('version',1,'sourceHash',repeat('d',64),'typeCode','SYN_AIM04','summary','SYNTHETIC summary','tagNames','[]'::jsonb,'semantic','pending_accepted_review'),'provenance','{"provider":"synthetic","model":"synthetic","promptVersion":"synthetic","durationMs":0}'::jsonb)::text,false);
SELECT set_config('test.receipt',public.ai_mod04_intake_stage('complete',current_setting('test.publish')::jsonb)::text,false);
RESET ROLE;
SELECT pg_temp.ok(NOT EXISTS(SELECT 1 FROM erp_private.f07_intake_analyses WHERE result_id=1102),'REPRODUCED: baseline type result loses original evidence');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001001","role":"authenticated","session_id":"00000000-0000-4000-8000-000000002001"}',false); SET ROLE authenticated;
SELECT pg_temp.ok((public.f07_prepare_intake_review(1101,1001,NULL)->>'requiresOverride')::boolean,'REPRODUCED: unchanged verified file incorrectly needs exception after type extraction');
RESET ROLE;
-- APPLY_EXACT_MIGRATION
SELECT pg_temp.ok(EXISTS(SELECT 1 FROM erp_private.f07_intake_analyses WHERE result_id=1102),'migration recovers valid retained stage without another analysis');
SELECT pg_temp.ok((SELECT status='complete' FROM public.dms_ai_extraction_jobs WHERE id=1102),'legacy publisher status normalized for verified job only');
SELECT pg_temp.ok(erp_private.reconcile_intake_type_analysis(1102)='already_verified','recovery is idempotent');
SELECT pg_temp.ok((SELECT count(*) FROM public.dms_ai_extraction_jobs)=2,'recovery creates no AI jobs');
SELECT pg_temp.ok((SELECT extracted_fields_json->>'number' FROM public.dms_ai_extraction_results WHERE id=1101)='OLD','root result preserved');
SELECT pg_temp.ok((SELECT document_id IS NULL AND intake_status='review_pending' FROM public.dms_upload_sessions WHERE id=1101),'recovery does not approve or create a document');
SET ROLE authenticated;
SELECT pg_temp.error($q$SELECT erp_private.reconcile_intake_type_analysis(1102)$q$,'42501','ordinary caller cannot mint proof');
SELECT set_config('test.plan',public.f07_prepare_intake_review(1101,1001,NULL)::text,false);
SELECT pg_temp.ok(NOT (current_setting('test.plan')::jsonb->>'requiresOverride')::boolean,'recovered result no longer requires artificial override');
SELECT pg_temp.ok(public.f07_confirm_intake_review(1101,1001,NULL,current_setting('test.plan')::jsonb->>'fingerprint',true,false,NULL)->>'mode'='verified','normal explicit human confirmation succeeds');
SELECT pg_temp.ok(public.f07_confirm_intake_review(1101,1001,NULL,current_setting('test.plan')::jsonb->>'fingerprint',true,false,NULL)->>'mode'='verified','lost confirmation response is safely retryable');
SELECT erp_private.f07_assert_intake_review(1101,1001,NULL);
SELECT pg_temp.ok(true,'approval gate accepts the exact recovered and human-confirmed review');
SELECT pg_temp.error($q$SELECT public.f07_confirm_intake_review(1101,1001,NULL,'stale',true,false,NULL)$q$,'PT409','stale confirmation remains blocked');
SELECT pg_temp.error($q$SELECT public.f07_confirm_intake_review(1101,1001,NULL,current_setting('test.plan')::jsonb->>'fingerprint',false,false,NULL)$q$,'PT409','human confirmation still required');
SELECT pg_temp.ok(public.ai_mod04_intake_stage('begin',current_setting('test.request')::jsonb)->'receipt'=current_setting('test.receipt')::jsonb->'receipt','retained completion is reused without provider work');
SELECT set_config('test.request','{"uploadSessionId":1101,"documentTypeId":1001,"mergeMode":"fill_missing_only"}',false);
SELECT set_config('test.stage',public.ai_mod04_intake_stage('begin',current_setting('test.request')::jsonb)::text,false);
SELECT pg_temp.ok(current_setting('test.stage')::jsonb->>'state'='started','new mode can be admitted from verified result');
SELECT pg_temp.ok(public.ai_mod04_intake_stage('begin',current_setting('test.request')::jsonb)->>'state'='uncertain','duplicate admission cannot duplicate provider work');
SELECT pg_temp.error($q$SELECT public.ai_mod04_intake_stage('complete',current_setting('test.publish')::jsonb)$q$,'42501','interactive caller cannot publish analysis');
RESET ROLE; SELECT set_config('request.jwt.claims','{"role":"service_role"}',false); SET ROLE service_role;
SELECT set_config('test.publish',(current_setting('test.publish')::jsonb||jsonb_build_object('token',current_setting('test.stage')::jsonb->>'token'))::text,false);
SELECT set_config('test.receipt2',public.ai_mod04_intake_stage('complete',current_setting('test.publish')::jsonb)::text,false);
SELECT pg_temp.ok(public.ai_mod04_intake_stage('complete',current_setting('test.publish')::jsonb)=current_setting('test.receipt2')::jsonb,'publication response loss creates no duplicate result');
RESET ROLE;
SELECT pg_temp.ok(EXISTS(SELECT 1 FROM erp_private.f07_intake_analyses WHERE result_id=1103),'future publisher atomically retains verified proof');
SELECT pg_temp.ok((SELECT count(*) FROM public.dms_ai_extraction_results)=3,'only expected three analysis results exist');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001001","role":"authenticated","session_id":"00000000-0000-4000-8000-000000002001"}',false); SET ROLE authenticated;
SELECT pg_temp.ok(NOT (public.f07_prepare_intake_review(1101,1001,NULL)->>'requiresOverride')::boolean,'new type result is reviewable without override');
SELECT pg_temp.error($q$SELECT erp_private.f07_assert_intake_review(1101,1001,NULL)$q$,'PT409','previous human approval cannot carry over to a replacement analysis');
RESET ROLE;
SAVEPOINT evidence_cases;
DELETE FROM erp_private.f07_intake_analyses WHERE result_id=1103;
UPDATE erp_private.ai_mod04_intake_stages SET receipt=jsonb_set(receipt,'{extractedFieldsJson,number}','"TAMPERED"') WHERE receipt->>'resultId'='1103';
SELECT pg_temp.ok(erp_private.reconcile_intake_type_analysis(1103)='held_receipt_mismatch','tampered receipt cannot recover');
ROLLBACK TO SAVEPOINT evidence_cases;
DELETE FROM erp_private.f07_intake_analyses WHERE result_id=1103;
