SELECT pg_temp.ok(NOT EXISTS(SELECT 1 FROM erp_private.f07_intake_analyses WHERE result_id=1103),'expired recovery does not append proof');
ROLLBACK TO SAVEPOINT evidence_cases;
UPDATE public.dms_upload_sessions SET expires_at=clock_timestamp()-interval '1 second' WHERE id=1101;
SELECT pg_temp.ok(erp_private.reconcile_intake_type_analysis(1103)='held_closed_source','elapsed expiry holds even before status is marked expired');
ROLLBACK TO SAVEPOINT evidence_cases;
DELETE FROM erp_private.f07_intake_analyses WHERE result_id=1103;
DELETE FROM erp_private.f07_intake_sources WHERE upload_session_id=1101;
SELECT pg_temp.ok(erp_private.reconcile_intake_type_analysis(1103)='held_file_proof','a retained storage object does not replace verified file provenance');
ROLLBACK TO SAVEPOINT evidence_cases;
DELETE FROM erp_private.f07_intake_analyses WHERE result_id=1101;
SELECT pg_temp.ok(erp_private.reconcile_intake_type_analysis(1101)='held_no_type_receipt','a completed legacy job and matching original do not prove the saved result');
ROLLBACK TO SAVEPOINT evidence_cases;
DELETE FROM erp_private.f07_intake_analyses;
UPDATE public.dms_upload_sessions SET ai_result_id=1101 WHERE id=1101;
SET ROLE authenticated;
SELECT pg_temp.error($q$SELECT public.ai_mod04_intake_stage('begin','{"uploadSessionId":1101,"documentTypeId":1001,"mergeMode":"fill_missing_only"}')$q$,'PT409','unproven original blocks new paid admission');
